func TestMessagingEndpoint(t *testing.T) {
	cases := []struct{ goos, raw, want string }{
		{"darwin", "/tmp/cc.sock", "/tmp/cc.sock"},
	}
	for _, c := range cases {
		if got := IsBatch(c.goos, c.path); got != c.want {
			t.Errorf("IsBatch(%s, %s) = %v", c.goos, c.path, got)
		}
	}
}

